from dotenv.variables import _posix_variable, Literal, Variable

def buggy_parse(value):
    cursor = 0
    for match in _posix_variable.finditer(value):
        (start, end) = match.span()
        if start > cursor:
            yield Literal(value=value[cursor:start])
        yield Variable(name=match["name"], default=match["default"])
        cursor = start          # ← 缺陷
    length = len(value)
    if cursor < length:
        yield Literal(value=value[cursor:length])

env = {"X": "value", "Y": "second", "A": "one"}
for t in ["${X}${Y}", "one${A}", "pre-${X}-post", "a${A}${Y}b"]:
    print(f"{t!r:20} buggy={''.join(a.resolve(env) for a in buggy_parse(t))!r}")
EOF
